 } {
  value, err := (&SegmentEmbed{Segment: tc.segment}).MarshalYAML()
  require.NoError(t, err)
  if group, ok := value.(Segments); ok { require.Equal(t, tc.want, group.SegmentOperator) } else { require.Equal(t, tc.want, value) }
 }
 _, err := (&SegmentEmbed{}).MarshalYAML()
 require.Error(t, err)
}
